$('full').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>message('請使用瀏覽器的全螢幕功能'));};
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.repeat)return;if(e.key.toLowerCase()==='c')changeCamera();if(e.key.toLowerCase()==='r')recoverPlayer();if(e.key==='Escape')pause();});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{clearInputs();if(['race','countdown'].includes(state))pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInputs();if(['race','countdown'].includes(state))pause();}});
for(const [id,set] of [['gas',v=>touchGas=v],['brake',v=>touchBrake=v],['boost',v=>touchBoost=v]]){let b=$(id);b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);set(true);b.classList.add('pressed');};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>{set(false);b.classList.remove('pressed');};}
function slide(e){let rect=$('steerTrack').getBoundingClientRect();touchSteer=clamp((e.clientX-(rect.left+rect.width/2))/(rect.width*.47),-1,1);$('steerKnob').style.left=`${50+touchSteer*46}%`;}$('steerPad').onpointerdown=e=>{e.preventDefault();steerPointer=e.pointerId;$('steerPad').setPointerCapture(e.pointerId);slide(e);};$('steerPad').onpointermove=e=>{if(e.pointerId===steerPointer)slide(e);};$('steerPad').onpointerup=$('steerPad').onpointercancel=$('steerPad').onlostpointercapture=()=>{steerPointer=null;touchSteer=0;$('steerKnob').style.left='50%';};
function input(){let gas=touchGas||keys.has('w')||keys.has('arrowup')||$('autoGas').checked?1:0,brake=touchBrake||keys.has('s')||keys.has('arrowdown')?1:0,steer=touchSteer+(keys.has('a')||keys.has('arrowleft')?-1:0)+(keys.has('d')||keys.has('arrowright')?1:0),boost=touchBoost||keys.has(' ');let pad=navigator.getGamepads?.()[0];if(pad){steer+=Math.abs(pad.axes[0])>.08?pad.axes[0]:0;gas=Math.max(gas,pad.buttons[7]?.value||0);brake=Math.max(brake,pad.buttons[6]?.value||0);boost ||=pad.buttons[0]?.pressed;}if(brake>.1)gas=0;throttleInput=gas;brakeInput=brake;steerInput=clamp(steer,-1,1);boostInput=boost;return{gas,brake,steer:steerInput,boost};}
function updateAI(d,dt){const skill={easy:.73,normal:.88,hard:1.01}[difficulty]*d.aiSkill;let target=sample(d.aiD+18+d.aiSpeed*.25).limit*skill;for(let other of drivers){if(other===d)continue;let delta=other.distance-d.distance;if(delta>0&&delta<23&&Math.abs((other.player?other.near.offset:other.aiOffset)-d.aiOffset)<2.8){let desired=d.id%2?4:-4;d.aiOffset=lerp(d.aiOffset,desired,dt*1.8);if(delta<9)target=Math.min(target,Math.max(15,other.speed*.97));}}let laneTarget=Math.sin(d.aiD/180+d.id)*1.4;if(drivers.every(o=>o===d||Math.abs(o.distance-d.distance)>24))d.aiOffset=lerp(d.aiOffset,laneTarget,dt*.7);d.aiSpeed+=clamp(target-d.aiSpeed,-16*dt,10.8*dt);d.aiD+=d.aiSpeed*dt;let p=sample(d.aiD,d.aiOffset),prevX=d.x,prevZ=d.z;d.x=p.x;d.z=p.z;let desired=p.a;d.yaw=angleDiff(desired,d.a)/dt;d.a=desired;d.vx=(d.x-prevX)/dt;d.vz=(d.z-prevZ)/dt;d.speed=d.aiSpeed;d.distance=d.aiD;d.throttle=target>d.aiSpeed?1:.35;d.brake=target<d.aiSpeed-1?.5:0;d.steer=clamp(d.yaw*3.6/Math.max(5,d.speed),-.4,.4);let completed=Math.max(0,Math.floor(d.distance/LENGTH));if(completed>d.completed){d.completed=completed;d.lapTime=0;}d.lapTime+=dt;if(d.distance>=LENGTH*3&&!d.finished){d.finished=true;d.finishTime=raceTime;d.finishPlace=++finishRank;}}
function finish(){player.finished=true;player.finishTime=raceTime;player.finishPlace=++finishRank;state='finished';clearInputs();$('results').classList.remove('hidden');let rank=player.finishPlace;$('resultTitle').textContent=rank===1?'冠軍。屬於你。':rank<=3?`P${rank} · 站上頒獎台`:`P${rank} · 完成大獎賽`;$('resultSummary').textContent=`總時間 ${formatTime(raceTime)}　／　最佳圈 ${player.best?formatTime(player.best):'無有效圈速'}`;let sorted=[...drivers].sort((a,b)=>a.finished&&b.finished?a.finishPlace-b.finishPlace:a.finished?-1:b.finished?1:b.distance-a.distance);$('resultTable').innerHTML=sorted.map((d,i)=>`<div class="resultRow ${d.player?'you':''}"><span>${i+1}</span><span>${d.name}${d.player?' / PLAYER':''}</span><span>${d.finished?formatTime(d.finishTime):'未完賽'}</span></div>`).join('');}
function physics(dt){if(state==='countdown'){countdown-=dt;let lit=clamp(Math.floor(5.2-countdown),0,5);[...$('startLights').querySelectorAll('i')].forEach((el,i)=>el.classList.toggle('on',i<lit));$('startLights').querySelector('span').textContent=countdown<.4?'等待熄燈':'準備起跑';if(countdown<=0){state='race';$('startLights').classList.add('hidden');message('LIGHTS OUT · 全力起跑！',2.5);beep(880,.12);}return;}if(state!=='race')return;raceTime+=dt;const controls=input();if(player.recoveryHold>0){player.recoveryHold-=dt;controls.gas=0;controls.brake=1;}drive(player,controls,dt,$('assist').checked);for(let d of drivers)if(!d.player&&!d.finished)updateAI(d,dt);for(let d of drivers){if(d.player)continue;if(collide(player,d)&&player.collisionCooldown<=0){player.collisionCooldown=.7;shake=.22;d.aiSpeed*=.86;player.vx*=.91;player.vz*=.91;$('damageFlash').style.opacity='.5';setTimeout(()=>$('damageFlash').style.opacity='0',100);impact();}}
if(player.wallHit){player.wallHit=false;shake=.3;impact();}if(player.offTime>4){recover(player);player.recoveryHold=3;message('返回賽道 · 停車 3 秒');cameraSnap=true;}if(player.justLapped){let result=player.justLapped;player.justLapped=null;if(result.valid){message(`第 ${player.completed} 圈 · ${formatTime(result.time)}`);if(!bestStored||result.time<bestStored){bestStored=result.time;try{localStorage.setItem('apex-v2-best',String(bestStored));}catch{}$('best').textContent=formatTime(bestStored);}}else message('本圈超出賽道邊界 · 圈速無效');}if(mode==='race'&&player.distance>=LENGTH*3&&!player.finished)finish();}
function updateModels(dt){for(let d of drivers){d.model.position.set(d.x,.012+Math.sin(raceTime*45)*Math.min(.012,d.speed*.0002),d.z);d.model.rotation.set(0,d.a,clamp(-d.yaw*d.speed*.0006,-.025,.025));for(let w of d.model.userData.wheels){w.pivot.rotation.y=w.front?d.steer:0;w.tire.rotation.x-=d.speed*dt/.43;w.rim.rotation.x=w.tire.rotation.x;}}}
function cameraUpdate(dt,now){if(state==='menu'){let t=now*.00009,a=showcase.a+t;camera.position.set(showcase.x+Math.sin(a)*8.5,3.5,showcase.z+Math.cos(a)*8.5);camera.lookAt(showcase.x,.65,showcase.z);camera.fov=48;camera.updateProjectionMatrix();return;}if(!player)return;let a=player.a,fx=Math.sin(a),fz=Math.cos(a),rx=Math.cos(a),rz=-Math.sin(a),speed=player.speed,portrait=innerHeight>innerWidth;if(cameraMode===0){let back=portrait?11:9.5;tmp.set(player.x-fx*back,portrait?4.6:3.5,player.z-fz*back);let lookAhead=(portrait?3:7)+speed*(portrait?.10:.14);cameraLook.set(player.x+fx*lookAhead,1.05,player.z+fz*lookAhead);player.model.visible=true;}else{let offset=cameraMode===1?.03:2.1;tmp.set(player.x+fx*offset,cameraMode===1?1.19:.6,player.z+fz*offset);cameraLook.set(player.x+fx*90,1.5,player.z+fz*90);player.model.visible=cameraMode===1;}let smoothing=1-Math.exp(-dt*(cameraMode===0?7.5:22));if(cameraSnap){camera.position.copy(tmp);cameraPos.copy(cameraLook);cameraSnap=false;}else{camera.position.lerp(tmp,smoothing);cameraPos.lerp(cameraLook,Math.min(1,smoothing*1.2));}shake=Math.max(0,shake-dt);if(shake>0){camera.position.x+=(Math.random()-.5)*shake;camera.position.y+=(Math.random()-.5)*shake*.35;}camera.lookAt(cameraPos);let fov=(portrait?68:60)+clamp(speed/90,0,1)*8+(boostInput?2:0);camera.fov=lerp(camera.fov,fov,Math.min(1,dt*3));camera.updateProjectionMatrix();sun.position.set(player.x-70,140,player.z+65);sun.target.position.set(player.x,0,player.z);sun.target.updateMatrixWorld();}
const mapCtx=$('map').getContext('2d');let minX=Math.min(...path.map(p=>p.x)),maxX=Math.max(...path.map(p=>p.x)),minZ=Math.min(...path.map(p=>p.z)),maxZ=Math.max(...path.map(p=>p.z));function mapPoint(x,z){let scale=Math.min(180/(maxX-minX),120/(maxZ-minZ));return[15+(x-minX)*scale,15+(z-minZ)*scale];}function drawMap(){mapCtx.clearRect(0,0,210,150);mapCtx.beginPath();path.forEach((p,i)=>{let a=mapPoint(p.x,p.z);i?mapCtx.lineTo(...a):mapCtx.moveTo(...a);});mapCtx.closePath();mapCtx.strokeStyle='#6c8997';mapCtx.lineWidth=5;mapCtx.stroke();mapCtx.strokeStyle='#c4d6d8';mapCtx.lineWidth=1.5;mapCtx.stroke();for(let d of drivers){let p=mapPoint(d.x,d.z);mapCtx.fillStyle=d.player?'#dcff49':d.color;mapCtx.beginPath();mapCtx.arc(...p,d.player?4:2.6,0,Math.PI*2);mapCtx.fill();}}
function updateHud(){if(!player||state==='menu')return;let order=[...drivers].sort((a,b)=>a.finished&&b.finished?a.finishPlace-b.finishPlace:a.finished?-1:b.finished?1:b.distance-a.distance);$('position').textContent=order.indexOf(player)+1;$('lap').textContent=Math.min(mode==='race'?3:999,Math.max(1,Math.floor(player.distance/LENGTH)+1));$('lapTime').textContent=formatTime(player.lapTime);$('lapTime').style.color=player.invalid?'#ff9d85':'white';let speed=player.speed*3.6,gear=speed<2?'N':Math.min(8,Math.floor(speed/44)+1);$('speed').textContent=Math.round(speed);$('gear').textContent=gear;$('ers').textContent=Math.round(player.ers);$('gasBar').style.width=`${player.throttle*100}%`;$('brakeBar').style.width=`${player.brake*100}%`;let rpm=speed<2?.12:.32+(speed%44)/44*.68;revs.forEach((r,i)=>{r.classList.toggle('lit',i<rpm*12);r.classList.toggle('red',i>8);});for(let d of order){let row=$('leaderboard').querySelector(`[data-id="${d.id}"]`);row.style.order=order.indexOf(d);row.classList.toggle('mobileHide',order.indexOf(d)>2&&!d.player);row.querySelector('em').textContent=order.indexOf(d)+1;row.querySelector('small').textContent=d.player?'PLAYER':d.finished?'FIN':`+${Math.max(0,(order[0].distance-d.distance)/Math.max(20,d.speed)).toFixed(1)}`;}$('leaderboard').style.display='flex';$('leaderboard').style.flexDirection='column';let facing=Math.abs(angleDiff(player.a,player.near.a));$('wrongWay').classList.toggle('hidden',!(facing>2.1&&player.speed>3&&state==='race'));$('trackStatus').textContent=player.near.dist>HALF?'超出賽道 · 小心抓地力':'乾地 · 軟胎 · 26°C';drawMap();}
let audioCtx,master,engineGain,oscA,oscB,sound=false;function initAudio(){if(!sound)return;try{if(!audioCtx){audioCtx=new AudioContext();master=audioCtx.createGain();master.gain.value=.24;master.connect(audioCtx.destination);engineGain=audioCtx.createGain();engineGain.gain.value=0;let filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=2100;engineGain.connect(filter);filter.connect(master);oscA=audioCtx.createOscillator();oscB=audioCtx.createOscillator();oscA.type='sawtooth';oscB.type='triangle';oscA.connect(engineGain);oscB.connect(engineGain);oscA.start();oscB.start();}audioCtx.resume();}catch{sound=false;}}$('sound').onclick=()=>{sound=!sound;initAudio();$('sound').textContent=`音效 ${sound?'開':'關'}`;};function beep(freq,dur){if(!sound||!audioCtx)return;let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.15,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(master);o.start();o.stop(audioCtx.currentTime+dur);}function impact(){beep(70,.15);}function updateAudio(){if(!engineGain)return;let racing=['race','countdown'].includes(state)&&sound,speed=player?.speed*3.6||0,throttle=player?.throttle||0,f=95+(speed%44)*6+throttle*30;engineGain.gain.setTargetAtTime(racing?.07+throttle*.09:0,audioCtx.currentTime,.07);oscA.frequency.setTargetAtTime(f,audioCtx.currentTime,.04);oscB.frequency.setTargetAtTime(f*1.51,audioCtx.currentTime,.04);}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);cameraSnap=true;}window.addEventListener('resize',resize);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();if(['race','countdown'].includes(state))pause();message('圖形暫停，請重新整理頁面');});
function loop(now){let dt=Math.min(.05,(now-lastFrame)/1000||.016);lastFrame=now;if(state==='race'||state==='countdown'){acc+=dt;while(acc>=1/120){physics(1/120);acc-=1/120;}}else acc=0;if(messageTime>0){messageTime-=dt;if(messageTime<=0)$('message').classList.remove('show');}updateModels(dt);cameraUpdate(dt,now);uiTimer+=dt;if(uiTimer>.08){uiTimer=0;updateHud();}updateAudio();renderer.render(scene,camera);requestAnimationFrame(loop);}
