// Read-only QA state makes race regressions inspectable without coupling UI to tests.
window.apexState=()=>({state,mode,length:LENGTH,camera:cameraMode,position:player?drivers.filter(d=>d.distance>player.distance).length+1:0,speed:player?.speed,lap:player?.completed,cars:drivers.length});
